(function(){const ids=["demo_user","test_renter_user"];const allBookings=JSON.parse(localStorage.getItem("movanta_bookings")||"[]");const removedBookingIds=allBookings.filter(function(b){return ids.includes(b.userId)||ids.includes(b.ownerId);}).map(function(b){return b.id;});const keptBookings=allBookings.filter(function(b){return !ids.includes(b.userId)&&!ids.includes(b.ownerId);});localStorage.setItem("movanta_bookings",JSON.stringify(keptBookings));const allListings=JSON.parse(localStorage.getItem("movanta_listings")||"[]");const keptListings=allListings.filter(function(l){return !ids.includes(l.ownerId);});localStorage.setItem("movanta_listings",JSON.stringify(keptListings));const allMessages=JSON.parse(localStorage.getItem("movanta_messages")||"[]");const keptMessages=allMessages.filter(function(m){return !removedBookingIds.includes(m.bookingId);});localStorage.setItem("movanta_messages",JSON.stringify(keptMessages));console.log("Cleared "+(allBookings.length-keptBookings.length)+" booking(s), "+(allListings.length-keptListings.length)+" listing(s), "+(allMessages.length-keptMessages.length)+" message(s).");})();